#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    int P;
    cin >> P;

    vector<vector<bool>> black(L, vector<bool>(C, false));
    for (int i = 0; i < P; ++i) {
        int x, y;
        cin >> x >> y;
        black[x - 1][y - 1] = true;
    }

    vector<vector<bool>> eligible(L, vector<bool>(C, false));
    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (black[r][c]) continue;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    eligible[r][c] = true;
                    break;
                }
            }
        }
    }

    int count = 0;
    vector<vector<int>> match(L, vector<int>(C, -1));

    function<bool(int, int, vector<vector<bool>>&)> dfs =
        [&](int r, int c, vector<vector<bool>>& seen) {
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= L || nc < 0 || nc >= C || !eligible[nr][nc] || seen[nr][nc])
                    continue;

                seen[nr][nc] = true;
                if (match[nr][nc] == -1 || dfs(match[nr][nc] / C, match[nr][nc] % C, seen)) {
                    match[nr][nc] = r * C + c;
                    return true;
                }
            }
            return false;
        };

    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (!eligible[r][c]) continue;
            ++count;
            if ((r + c) % 2 == 0) {
                vector<vector<bool>> seen(L, vector<bool>(C, false));
                dfs(r, c, seen);
            }
        }
    }

    int matching = 0;
    for (int r = 0; r < L; ++r)
        for (int c = 0; c < C; ++c)
            if (match[r][c] != -1) ++matching;

    cout << count - matching << '\n';
    return 0;
}
